import hashlib, json

def block_hash(block):
    # hash SHA-256 della serializzazione canonica del blocco
    data = json.dumps(block, sort_keys=True).encode()
    return hashlib.sha256(data).hexdigest()

def build_chain(tx_lists):
    chain = []
    prev = "0" * 64                      # il blocco genesi punta a "zero"
    for i, txs in enumerate(tx_lists):
        block = {"height": i, "prev": prev, "txs": txs}
        chain.append(block)
        prev = block_hash(block)
    return chain

def verify(chain):
    # restituisce l'indice del primo blocco il cui campo prev non torna, o None
    for i in range(1, len(chain)):
        if chain[i]["prev"] != block_hash(chain[i - 1]):
            return i
    return None

chain = build_chain([["coinbase->Alice 50"],
                     ["Alice->Bob 10"],
                     ["Bob->Carol 5"],
                     ["Carol->Dave 1"]])
for b in chain:
    print(b["height"], b["prev"][:16], block_hash(b)[:16])
print("catena valida, primo errore:", verify(chain))

chain[1]["txs"] = ["Alice->Bob 1000"]    # manomissione di un blocco passato
print("dopo la manomissione, primo errore al blocco:", verify(chain))

