def t_client_server(N, F, us, dmin):
    # il server deve caricare N copie; il client più lento deve scaricarne una
    return max(N * F / us, F / dmin)

def t_p2p(N, F, us, dmin, u):
    # il server carica almeno una copia; il totale di N*F bit è caricato da server + N peer
    return max(F / us, F / dmin, N * F / (us + N * u))

F = 8e9        # file da 1 GB = 8e9 bit
us = 100e6     # upload server 100 Mbit/s
u = 10e6       # upload di ogni peer 10 Mbit/s
dmin = 50e6    # download del peer più lento 50 Mbit/s

print(f"{'N':>6} {'client-server (s)':>18} {'P2P (s)':>10}")
for N in (10, 100, 1000, 10000, 100000):
    print(f"{N:>6} {t_client_server(N, F, us, dmin):>18.0f} {t_p2p(N, F, us, dmin, u):>10.0f}")
print(f"limite P2P per N grande: F/u = {F / u:.0f} s")
